-- Generat per @talaia/worker astronomia:calendari. No l'editis a mà.
-- Procedència: Astronomy Engine; el seed 02 conserva les fonts IMO/NASA.

begin;

on conflict (codi) do update set
  tipus_codi = excluded.tipus_codi, periodicitat = excluded.periodicitat,
  publicable_calendari = excluded.publicable_calendari, textos = excluded.textos
where (fenomens_astronomics.tipus_codi, fenomens_astronomics.periodicitat, fenomens_astronomics.publicable_calendari, fenomens_astronomics.textos)
  is distinct from (excluded.tipus_codi, excluded.periodicitat, excluded.publicable_calendari, excluded.textos);

on conflict (codi) do update set
  fenomen_codi = excluded.fenomen_codi, font_codi = null, metode_calcul = excluded.metode_calcul,
  inici = excluded.inici, fi = excluded.fi, maxim = excluded.maxim, precisio = excluded.precisio,
  rellevant_catalunya = excluded.rellevant_catalunya, rellevancia = excluded.rellevancia,
  dificultat_observacio = excluded.dificultat_observacio, textos = excluded.textos,
  detall_calcul = excluded.detall_calcul
where (esdeveniments_astronomics.fenomen_codi, esdeveniments_astronomics.font_codi, esdeveniments_astronomics.metode_calcul, esdeveniments_astronomics.inici, esdeveniments_astronomics.fi, esdeveniments_astronomics.maxim, esdeveniments_astronomics.precisio, esdeveniments_astronomics.rellevant_catalunya, esdeveniments_astronomics.rellevancia, esdeveniments_astronomics.dificultat_observacio, esdeveniments_astronomics.textos, esdeveniments_astronomics.detall_calcul)
  is distinct from (excluded.fenomen_codi, null, excluded.metode_calcul, excluded.inici, excluded.fi, excluded.maxim, excluded.precisio, excluded.rellevant_catalunya, excluded.rellevancia, excluded.dificultat_observacio, excluded.textos, excluded.detall_calcul);

-- Si canvia el dia local o un criteri de selecció, elimina codis antics només d'aquest càlcul i període.
delete from public.esdeveniments_astronomics
where metode_calcul = 'Astronomy Engine 2.1.19'
  and maxim between '2026-10-01T00:00:00Z' and '2027-12-31T23:59:59Z'
  and codi not in ('conjuncio-lluna-mart-2026-10-05', 'conjuncio-lluna-jupiter-2026-10-06', 'lluna-nova-2026-10-10', 'lluna-plena-2026-10-26', 'conjuncio-lluna-jupiter-2026-11-03', 'conjuncio-lluna-venus-2026-11-07', 'lluna-nova-2026-11-09', 'conjuncio-mart-jupiter-2026-11-16', 'superlluna-plena-2026-11-24', 'conjuncio-lluna-jupiter-2026-11-30', 'lluna-nova-2026-12-09', 'superlluna-plena-2026-12-24', 'lluna-nova-2027-01-07', 'superlluna-plena-2027-01-22', 'conjuncio-lluna-jupiter-2027-01-23', 'lluna-nova-2027-02-06', 'conjuncio-lluna-jupiter-2027-02-20', 'superlluna-plena-2027-02-21', 'lluna-nova-2027-03-08', 'lluna-plena-2027-03-22', 'lluna-nova-2027-04-07', 'lluna-plena-2027-04-21', 'lluna-nova-2027-05-06', 'conjuncio-lluna-jupiter-2027-05-13', 'lluna-plena-2027-05-20', 'lluna-nova-2027-06-04', 'lluna-plena-2027-06-19', 'lluna-nova-2027-07-04', 'lluna-plena-2027-07-18', 'lluna-nova-2027-08-02', 'lluna-plena-2027-08-17', 'lluna-nova-2027-08-31', 'lluna-plena-2027-09-16', 'lluna-nova-2027-09-30', 'lluna-plena-2027-10-15', 'lluna-nova-2027-10-29', 'lluna-plena-2027-11-14', 'lluna-nova-2027-11-28', 'lluna-plena-2027-12-13', 'lluna-nova-2027-12-27');

